"use strict";(globalThis.webpackChunkstory=globalThis.webpackChunkstory||[]).push([[51893],{32672(n){n.exports=JSON.parse('{"tag":{"label":"nestjs","permalink":"/docs/tags/nestjs","allTagsPath":"/docs/tags","count":31,"items":[{"id":"nestjs/core-fundamentals/circular-dependency","title":"[NestJS] Circular Dependency: L\u1ed7i V\xf2ng L\u1eb7p & C\xe1ch H\xf3a Gi\u1ea3i","description":"Ph\xe2n t\xedch nguy\xean nh\xe2n c\u1ed1t l\xf5i g\xe2y ra l\u1ed7i Circular Dependency (ph\u1ee5 thu\u1ed9c v\xf2ng tr\xf2n) v\xe0 h\u01b0\u1edbng d\u1eabn 2 gi\u1ea3i ph\xe1p tri\u1ec7t \u0111\u1ec3: forwardRef() v\xe0 t\xe1i c\u1ea5u tr\xfac ki\u1ebfn tr\xfac.","permalink":"/docs/nestjs/core-fundamentals/circular-dependency"},{"id":"nestjs/building-blocks/controllers","title":"[NestJS] Controllers: C\u1ed5ng \u0110i\u1ec1u Ph\u1ed1i HTTP Request","description":"H\u01b0\u1edbng d\u1eabn chi ti\u1ebft v\u1ec1 NestJS Controllers. N\u1eafm v\u1eefng Routing, c\xe1c Param Decorators (@Param, @Query, @Body), ki\u1ec3m so\xe1t Response Code, v\xe0 thi\u1ebft k\u1ebf DTO \u0111\xfang chu\u1ea9n.","permalink":"/docs/nestjs/building-blocks/controllers"},{"id":"nestjs/aop-layer/custom-decorators","title":"[NestJS] Custom Decorators: Ngh\u1ec7 Thu\u1eadt \u0110\xf3ng G\xf3i Code (Composition)","description":"H\u01b0\u1edbng d\u1eabn t\u1ea1o Custom Param Decorators v\xe0 \u1ee9ng d\u1ee5ng Decorator Composition (applyDecorators) \u0111\u1ec3 d\u1ecdn d\u1eb9p Boilerplate code trong Controller.","permalink":"/docs/nestjs/aop-layer/custom-decorators"},{"id":"nestjs/core-fundamentals/custom-providers","title":"[NestJS] Custom Providers: L\xe0m Ch\u1ee7 Dependency Injection N\xe2ng Cao","description":"Kh\xe1m ph\xe1 s\u1ee9c m\u1ea1nh th\u1ef1c s\u1ef1 c\u1ee7a Dependency Injection trong NestJS th\xf4ng qua Custom Providers. H\u01b0\u1edbng d\u1eabn chi ti\u1ebft useValue, useClass, useFactory v\xe0 useExisting.","permalink":"/docs/nestjs/core-fundamentals/custom-providers"},{"id":"nestjs/core-fundamentals/dynamic-modules","title":"[NestJS] Dynamic Modules: Ki\u1ebfn Tr\xfac Plugin & ConfigurableModuleBuilder","description":"Hi\u1ec3u s\xe2u v\u1ec1 Dynamic Modules. C\xe1ch truy\u1ec1n tham s\u1ed1 c\u1ea5u h\xecnh khi import, ph\xe2n bi\u1ec7t register/forRoot/forFeature v\xe0 c\xe1ch s\u1eed d\u1ee5ng ConfigurableModuleBuilder \u0111\u1ec3 t\u1ea1o module chu\u1ea9n.","permalink":"/docs/nestjs/core-fundamentals/dynamic-modules"},{"id":"nestjs/aop-layer/exception-filters","title":"[NestJS] Exception Filters: T\u1ea5m L\u01b0\u1edbi L\u1ecdc L\u1ed7i An To\xe0n","description":"C\xe1ch ki\u1ec3m so\xe1t ho\xe0n to\xe0n h\u1ec7 th\u1ed1ng x\u1eed l\xfd l\u1ed7i trong NestJS. H\u01b0\u1edbng d\u1eabn vi\u1ebft Custom Exception v\xe0 x\xe2y d\u1ef1ng Exception Filter \u0111\u1ec3 chu\u1ea9n h\xf3a \u0111\u1ecbnh d\u1ea1ng JSON tr\u1ea3 v\u1ec1 cho Client.","permalink":"/docs/nestjs/aop-layer/exception-filters"},{"id":"nestjs/core-fundamentals/execution-context","title":"[NestJS] Execution Context & Reflection: Linh H\u1ed3n C\u1ee7a Middleware","description":"Kh\xe1m ph\xe1 Execution Context v\xe0 Reflector. \u0110\xe2y l\xe0 ki\u1ebfn th\u1ee9c c\u1ed1t l\xf5i gi\xfap b\u1ea1n vi\u1ebft Guards, Interceptors v\xe0 Custom Decorators linh ho\u1ea1t tr\xean m\u1ecdi n\u1ec1n t\u1ea3ng (HTTP, GraphQL, RPC).","permalink":"/docs/nestjs/core-fundamentals/execution-context"},{"id":"nestjs/aop-layer/guards","title":"[NestJS] Guards: Ng\u01b0\u1eddi G\xe1c C\u1ed5ng Ph\xe2n Quy\u1ec1n (Authentication & Authorization)","description":"Hi\u1ec3u s\xe2u v\u1ec1 Guards trong NestJS. H\u01b0\u1edbng d\u1eabn chi ti\u1ebft c\xe1ch s\u1eed d\u1ee5ng ExecutionContext v\xe0 Reflector \u0111\u1ec3 x\xe2y d\u1ef1ng h\u1ec7 th\u1ed1ng ph\xe2n quy\u1ec1n Role-Based Access Control (RBAC).","permalink":"/docs/nestjs/aop-layer/guards"},{"id":"nestjs/core-fundamentals/injection-scopes","title":"[NestJS] Injection Scopes: Qu\u1ea3n L\xfd V\xf2ng \u0110\u1eddi C\u1ee7a Provider","description":"Hi\u1ec3u r\xf5 v\u1ec1 3 lo\u1ea1i Injection Scope (Singleton, Request, Transient) trong NestJS. Tr\xe1nh c\xe1c l\u1ed7i Memory Leak v\xe0 t\u1ed1i \u01b0u hi\u1ec7u n\u0103ng cho h\u1ec7 th\u1ed1ng Node.js.","permalink":"/docs/nestjs/core-fundamentals/injection-scopes"},{"id":"nestjs/aop-layer/interceptors","title":"[NestJS] Interceptors: Quy\u1ec1n N\u0103ng Thao T\xe1c Stream (Before & After)","description":"Kh\xe1m ph\xe1 Interceptors trong NestJS. H\u01b0\u1edbng d\u1eabn s\u1eed d\u1ee5ng RxJS Observables \u0111\u1ec3 can thi\u1ec7p v\xe0o lu\u1ed3ng Request/Response v\u1edbi c\xe1c use-case: Logging, Response Mapping, Exception Mapping v\xe0 Caching.","permalink":"/docs/nestjs/aop-layer/interceptors"},{"id":"nestjs/core-fundamentals/lifecycle-events","title":"[NestJS] Lifecycle Events: Qu\u1ea3n L\xfd V\xf2ng \u0110\u1eddi \u1ee8ng D\u1ee5ng","description":"L\xe0m ch\u1ee7 3 giai \u0111o\u1ea1n v\xf2ng \u0111\u1eddi c\u1ee7a m\u1ed9t \u1ee9ng d\u1ee5ng NestJS. H\u01b0\u1edbng d\u1eabn s\u1eed d\u1ee5ng Lifecycle Hooks \u0111\u1ec3 kh\u1edfi t\u1ea1o t\xe0i nguy\xean v\xe0 th\u1ef1c hi\u1ec7n Graceful Shutdown an to\xe0n.","permalink":"/docs/nestjs/core-fundamentals/lifecycle-events"},{"id":"nestjs/building-blocks/middleware","title":"[NestJS] Middleware: L\u1edbp Ti\u1ec1n X\u1eed L\xfd Request (Tr\u01b0\u1edbc Khi \u0110\u1ebfn Controller)","description":"Middleware trong NestJS l\xe0 g\xec? H\u01b0\u1edbng d\u1eabn t\u1ea1o Class v\xe0 Functional Middleware, c\u01a1 ch\u1ebf \u0111\u0103ng k\xfd v\u1edbi MiddlewareConsumer, v\xe0 gi\u1ea3i th\xedch gi\u1edbi h\u1ea1n c\u1ee7a Middleware so v\u1edbi Guards.","permalink":"/docs/nestjs/building-blocks/middleware"},{"id":"nestjs/building-blocks/modules","title":"[NestJS] Modules: Ki\u1ebfn Tr\xfac M\xf4-\u0111un H\xf3a (Feature, Shared & Global)","description":"Hi\u1ec3u s\xe2u v\u1ec1 NestJS Modules. H\u01b0\u1edbng d\u1eabn t\u1ed5 ch\u1ee9c codebase theo Feature Modules, c\u01a1 ch\u1ebf Shared Module \u0111\u1ec3 d\xf9ng chung Providers, v\xe0 Trade-off khi d\xf9ng Global Module.","permalink":"/docs/nestjs/building-blocks/modules"},{"id":"nestjs/aop-layer/pipes","title":"[NestJS] Pipes: B\u1ed9 L\u1ecdc D\u1eef Li\u1ec7u Tinh (Transformation & Validation)","description":"Pipes trong NestJS l\xe0 g\xec? H\u01b0\u1edbng d\u1eabn c\xe1ch s\u1eed d\u1ee5ng Pipes \u0111\u1ec3 Transformation (bi\u1ebfn \u0111\u1ed5i d\u1eef li\u1ec7u) v\xe0 Validation (x\xe1c th\u1ef1c d\u1eef li\u1ec7u) v\u1edbi class-validator.","permalink":"/docs/nestjs/aop-layer/pipes"},{"id":"nestjs/building-blocks/providers","title":"[NestJS] Providers: Tr\xe1i Tim C\u1ee7a H\u1ec7 Th\u1ed1ng Dependency Injection","description":"Providers trong NestJS l\xe0 g\xec? H\u01b0\u1edbng d\u1eabn t\u1ea1o Service, hi\u1ec3u c\u01a1 ch\u1ebf Singleton v\xe0 Dependency Injection, ph\xe2n bi\u1ec7t Constructor-based vs Property-based Injection.","permalink":"/docs/nestjs/building-blocks/providers"},{"id":"nestjs/aop-layer/aop","title":"AOP trong NestJS: Ki\u1ebfn tr\xfac \'Ch\u1eb7n \u0110\u1ee9ng\' Cross-Cutting Concerns","description":"Kh\xe1m ph\xe1 Aspect-Oriented Programming (AOP) trong NestJS \u2014 hi\u1ec3u t\u1ea1i sao Guards, Interceptors, Pipes, v\xe0 Exception Filters l\xe0 c\xe1ch NestJS hi\u1ec7n th\u1ef1c h\xf3a t\u01b0 t\u01b0\u1edfng AOP \u0111\u1ec3 t\xe1ch bi\u1ec7t logic nghi\u1ec7p v\u1ee5 kh\u1ecfi c\xe1c cross-cutting concerns.","permalink":"/docs/nestjs/aop-layer/aop"},{"id":"nestjs/aop-layer/aop-overview","title":"AOP trong NestJS: Ki\u1ebfn tr\xfac Ch\u1eb7n \u0110\u1ee9ng Cross-Cutting Concerns","description":"Kh\xe1m ph\xe1 Aspect-Oriented Programming (AOP) trong NestJS \u2014 hi\u1ec3u t\u1ea1i sao Guards, Interceptors, Pipes, v\xe0 Exception Filters l\xe0 c\xe1ch NestJS hi\u1ec7n th\u1ef1c h\xf3a t\u01b0 t\u01b0\u1edfng AOP \u0111\u1ec3 t\xe1ch bi\u1ec7t logic nghi\u1ec7p v\u1ee5 kh\u1ecfi c\xe1c cross-cutting concerns.","permalink":"/docs/nestjs/aop-layer/aop-overview"},{"id":"nestjs/tooling/debug-vscode","title":"C\xf4ng C\u1ee5 (Ph\u1ea7n 1): Debugger VSCode - Ngh\u1ec7 Thu\u1eadt G\u1ee1 L\u1ed7i Trong NestJS","description":"B\u1ecf qua console.log th\u1ee7 c\xf4ng, l\xe0m ch\u1ee7 Inspector Protocol, Source Maps v\xe0 c\u1ea5u h\xecnh launch.json chu\u1ea9n m\u1ef1c \u0111\u1ec3 debug d\u1ef1 \xe1n NestJS tr\u1ef1c ti\u1ebfp tr\xean VSCode.","permalink":"/docs/nestjs/tooling/debug-nodejs-nestjs-vscode"},{"id":"nestjs/tooling/logger","title":"C\xf4ng C\u1ee5 (Ph\u1ea7n 2): Ki\u1ebfn Tr\xfac Logger - T\u1eeb Built-in \u0110\u1ebfn Winston","description":"H\u01b0\u1edbng d\u1eabn to\xe0n di\u1ec7n v\u1ec1 c\u01a1 ch\u1ebf ghi nh\u1eadn s\u1ef1 ki\u1ec7n (Logging) trong NestJS. T\xedch h\u1ee3p Winston, File Rotation v\xe0 gi\u1ea3i quy\u1ebft b\xe0i to\xe1n hi\u1ec7u su\u1ea5t I/O tr\xean Production.","permalink":"/docs/nestjs/tooling/logger"},{"id":"nestjs/project/week5-plan","title":"NestJS: Create Quiz game engine","description":"T\xecm hi\u1ec3u NestJS t\u1eeb c\u01a1 b\u1ea3n \u0111\u1ebfn n\xe2ng cao: kh\xe1i ni\u1ec7m, th\xe0nh ph\u1ea7n ch\xednh, c\xe1ch tri\u1ec3n khai, use cases th\u1ef1c t\u1ebf v\xe0 best practices \u0111\u1ec3 t\u1ef1 \u0111\u1ed9ng h\xf3a quy tr\xecnh ph\xe1t tri\u1ec3n ph\u1ea7n m\u1ec1m.","permalink":"/docs/nestjs/project/week5-plan"},{"id":"nestjs/project/week1-plan","title":"NestJS: Ki\u1ebfn Th\u1ee9c N\u1ec1n T\u1ea3ng & Setup M\xf4i Tr\u01b0\u1eddng","description":"T\xecm hi\u1ec3u NestJS t\u1eeb c\u01a1 b\u1ea3n \u0111\u1ebfn n\xe2ng cao: kh\xe1i ni\u1ec7m, th\xe0nh ph\u1ea7n ch\xednh, c\xe1ch tri\u1ec3n khai, use cases th\u1ef1c t\u1ebf v\xe0 best practices \u0111\u1ec3 t\u1ef1 \u0111\u1ed9ng h\xf3a quy tr\xecnh ph\xe1t tri\u1ec3n ph\u1ea7n m\u1ec1m.","permalink":"/docs/nestjs/project/week1-plan"},{"id":"nestjs/project/week6-plan","title":"NestJS: Polishing and testing","description":"T\xecm hi\u1ec3u NestJS t\u1eeb c\u01a1 b\u1ea3n \u0111\u1ebfn n\xe2ng cao: kh\xe1i ni\u1ec7m, th\xe0nh ph\u1ea7n ch\xednh, c\xe1ch tri\u1ec3n khai, use cases th\u1ef1c t\u1ebf v\xe0 best practices \u0111\u1ec3 t\u1ef1 \u0111\u1ed9ng h\xf3a quy tr\xecnh ph\xe1t tri\u1ec3n ph\u1ea7n m\u1ec1m.","permalink":"/docs/nestjs/project/week6-plan"},{"id":"nestjs/project/week4-plan","title":"NestJS: Redis integration","description":"T\xecm hi\u1ec3u NestJS t\u1eeb c\u01a1 b\u1ea3n \u0111\u1ebfn n\xe2ng cao: kh\xe1i ni\u1ec7m, th\xe0nh ph\u1ea7n ch\xednh, c\xe1ch tri\u1ec3n khai, use cases th\u1ef1c t\u1ebf v\xe0 best practices \u0111\u1ec3 t\u1ef1 \u0111\u1ed9ng h\xf3a quy tr\xecnh ph\xe1t tri\u1ec3n ph\u1ea7n m\u1ec1m.","permalink":"/docs/nestjs/project/week4-plan"},{"id":"nestjs/project/week2-plan","title":"NestJS: TypeORM & Authentication","description":"T\xecm hi\u1ec3u NestJS t\u1eeb c\u01a1 b\u1ea3n \u0111\u1ebfn n\xe2ng cao: kh\xe1i ni\u1ec7m, th\xe0nh ph\u1ea7n ch\xednh, c\xe1ch tri\u1ec3n khai, use cases th\u1ef1c t\u1ebf v\xe0 best practices \u0111\u1ec3 t\u1ef1 \u0111\u1ed9ng h\xf3a quy tr\xecnh ph\xe1t tri\u1ec3n ph\u1ea7n m\u1ec1m.","permalink":"/docs/nestjs/project/week2-plan"},{"id":"nestjs/project/week3-plan","title":"NestJS: websocket and gateway basics","description":"T\xecm hi\u1ec3u NestJS t\u1eeb c\u01a1 b\u1ea3n \u0111\u1ebfn n\xe2ng cao: kh\xe1i ni\u1ec7m, th\xe0nh ph\u1ea7n ch\xednh, c\xe1ch tri\u1ec3n khai, use cases th\u1ef1c t\u1ebf v\xe0 best practices \u0111\u1ec3 t\u1ef1 \u0111\u1ed9ng h\xf3a quy tr\xecnh ph\xe1t tri\u1ec3n ph\u1ea7n m\u1ec1m.","permalink":"/docs/nestjs/project/week3-plan"},{"id":"nestjs/oop/foundation","title":"OOP trong NestJS (Ph\u1ea7n 1): T\u1eeb Function \u0111\u1ebfn Class - N\u1ec1n T\u1ea3ng Cho React/Node Developer","description":"Hi\u1ec3u b\u1ea3n ch\u1ea5t OOP trong NestJS t\u1eeb g\xf3c nh\xecn c\u1ee7a Functional Programming developer. So s\xe1nh Express (functional) v\u1edbi NestJS (OOP), gi\u1ea3i th\xedch this keyword, constructor patterns v\xe0 c\xe1ch chuy\u1ec3n \u0111\u1ed5i t\u01b0 duy.","permalink":"/docs/nestjs/oop/foundation"},{"id":"nestjs/oop/encapsulation-decorators","title":"OOP trong NestJS (Ph\u1ea7n 2): Encapsulation & Decorators - Gi\u1ea3i M\xe3 Ph\xe9p M\xe0u","description":"Hi\u1ec3u s\xe2u Encapsulation (\u0111\xf3ng g\xf3i) v\xe0 Decorators trong NestJS. Gi\u1ea3i th\xedch c\xe1ch @Controller, @Injectable ho\u1ea1t \u0111\u1ed9ng d\u01b0\u1edbi hood, v\xe0 c\xe1ch t\u1ef1 t\u1ea1o custom decorators.","permalink":"/docs/nestjs/oop/encapsulation-decorators"},{"id":"nestjs/oop/interface-abstract","title":"OOP trong NestJS (Ph\u1ea7n 3): Interface vs Abstract Class - Cu\u1ed9c Chi\u1ebfn Runtime v\xe0 Compile-time","description":"Ph\xe2n bi\u1ec7t r\xf5 r\xe0ng Interface v\xe0 Abstract Class trong TypeScript. Gi\u1ea3i th\xedch l\xfd do t\u1ea1i sao kh\xf4ng th\u1ec3 d\xf9ng Interface l\xe0m DI Token trong NestJS v\xe0 c\xe1ch x\xe2y d\u1ef1ng Base Repository chu\u1ea9n m\u1ef1c.","permalink":"/docs/nestjs/oop/interface-abstract"},{"id":"nestjs/oop/dependency-injection","title":"OOP trong NestJS (Ph\u1ea7n 4): Dependency Injection & IoC Container - Tr\xe1i Tim C\u1ee7a Framework","description":"Kh\xe1m ph\xe1 nguy\xean l\xfd Inversion of Control (IoC) v\xe0 Dependency Injection (DI) trong NestJS. H\u01b0\u1edbng d\u1eabn chi ti\u1ebft c\xe1ch c\u1ea5u h\xecnh Custom Providers (useValue, useFactory, useClass) v\xe0 x\u1eed l\xfd Optional Injection.","permalink":"/docs/nestjs/oop/dependency-injection"},{"id":"nestjs/oop/solid","title":"OOP trong NestJS (Ph\u1ea7n 5): SOLID Principles - Nguy\xean T\u1eafc Thi\u1ebft K\u1ebf B\u1ec1n V\u1eefng","description":"\xc1p d\u1ee5ng 5 nguy\xean t\u1eafc SOLID trong NestJS. Gi\u1ea3i th\xedch b\u1ea3n ch\u1ea5t, c\u1ea1m b\u1eaby th\u01b0\u1eddng g\u1eb7p v\xe0 v\xed d\u1ee5 refactoring t\u1eeb codebase th\u1ef1c t\u1ebf trong m\xf4i tr\u01b0\u1eddng Enterprise.","permalink":"/docs/nestjs/oop/solid"},{"id":"nestjs/oop/design-patterns","title":"OOP trong NestJS (Ph\u1ea7n 6): Design Patterns - Tinh Hoa Ki\u1ebfn Tr\xfac Enterprise","description":"T\u1ed5ng h\u1ee3p 4 Design Patterns c\u1ed1t l\xf5i l\xe0m n\xean s\u1ee9c m\u1ea1nh c\u1ee7a NestJS: Factory, Repository, Singleton v\xe0 Decorator. Ph\xe2n t\xedch t\xe1c \u0111\u1ed9ng hi\u1ec7u n\u0103ng c\u1ee7a Scope.","permalink":"/docs/nestjs/oop/design-patterns"}],"unlisted":false}}')}}]);